create or replace function public.test_lab_reset(p_operation text) returns void language plpgsql security definer set search_path=public as $$ declare v_product uuid; begin if not public.can_use_test_lab() then raise exception 'Área de teste restrita'; end if; if p_operation not in ('supplements','fitness') then raise exception 'Operação de teste inválida'; end if; delete from public.test_lab_purchase_orders where operation=p_operation; delete from public.test_lab_sales where operation=p_operation; delete from public.test_lab_customers where operation=p_operation; delete from public.test_lab_suppliers where operation=p_operation; delete from public.test_lab_inventory_movements where operation=p_operation; delete from public.test_lab_audit_events where operation=p_operation; delete from public.test_lab_products where operation=p_operation; insert into public.test_lab_customers(operation,name,phone) values(p_operation,'Cliente Teste 1','31999990001'),(p_operation,'Cliente Teste 2','31999990002'); insert into public.test_lab_suppliers(operation,name) values(p_operation,'Fornecedor Teste'); if p_operation='supplements' then insert into public.test_lab_products(operation,name,category,cost_price,sale_price) values(p_operation,'Creatina Teste 300g','Força',30,70),(p_operation,'Whey Teste 1kg','Massa',60,110),(p_operation,'Pré-treino Teste','Energia',35,65); else insert into public.test_lab_products(operation,name,category,variant_label,cost_price,sale_price) values(p_operation,'Legging Teste','Legging','M · Preto',30,59.90),(p_operation,'Conjunto Run Teste','Conjunto','P · Rosa',45,89.90),(p_operation,'Macacão Teste','Macacão','G · Vinho',50,99.90); end if; for v_product in select id from public.test_lab_products where operation=p_operation loop insert into public.test_lab_stock(product_id,quantity) values(v_product,10); end loop; insert into public.test_lab_audit_events(operation,entity_type,action,details) values(p_operation,'environment','reset',jsonb_build_object('seed_products',3,'seed_stock_per_product',10)); end; $$;
create or replace function public.test_lab_create_sale(p_operation text,p_customer_id uuid,p_items jsonb,p_paid boolean default false,p_delivered boolean default false,p_notes text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_sale_id uuid; v_item record; v_product public.test_lab_products%rowtype; v_item_id uuid; v_physical integer; v_reserved integer; v_available integer; v_reserve integer; v_status text; v_total_cost numeric(12,2):=0; v_total_amount numeric(12,2):=0; begin if not public.can_use_test_lab() then raise exception 'Área de teste restrita'; end if; if p_operation not in ('supplements','fitness') then raise exception 'Operação inválida'; end if; if not exists(select 1 from public.test_lab_customers where id=p_customer_id and operation=p_operation) then raise exception 'Cliente de teste inválido'; end if; if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Adicione itens à venda de teste'; end if; insert into public.test_lab_sales(operation,customer_id,payment_status,delivery_status,general_status,notes) values(p_operation,p_customer_id,case when p_paid then 'received' else 'receivable' end,case when p_delivered then 'delivered' else 'to_deliver' end,case when p_paid and p_delivered then 'finalized' else 'active' end,nullif(btrim(p_notes),'')) returning id into v_sale_id; for v_item in select * from jsonb_to_recordset(p_items) as x(product_id uuid,quantity integer) loop if coalesce(v_item.quantity,0)<=0 then raise exception 'Quantidade inválida'; end if; select * into v_product from public.test_lab_products where id=v_item.product_id and operation=p_operation and active; if not found then raise exception 'Produto de teste inválido'; end if; insert into public.test_lab_sale_items(sale_id,product_id,quantity,unit_cost,unit_price) values(v_sale_id,v_product.id,v_item.quantity,v_product.cost_price,v_product.sale_price) returning id into v_item_id; v_total_cost:=v_total_cost+(v_product.cost_price*v_item.quantity); v_total_amount:=v_total_amount+(v_product.sale_price*v_item.quantity); select quantity into v_physical from public.test_lab_stock where product_id=v_product.id for update; select coalesce(sum(quantity_reserved),0)::integer into v_reserved from public.test_lab_reservations where product_id=v_product.id and status in ('reserved','partial'); v_available:=greatest(coalesce(v_physical,0)-v_reserved,0); if p_delivered then if v_available<v_item.quantity then raise exception 'Estoque de teste insuficiente para %',v_product.name; end if; insert into public.test_lab_inventory_movements(operation,product_id,sale_id,movement_type,quantity_delta,notes) values(p_operation,v_product.id,v_sale_id,'sale',-v_item.quantity,'Baixa da venda de teste'); insert into public.test_lab_reservations(sale_id,sale_item_id,product_id,quantity_requested,quantity_reserved,status) values(v_sale_id,v_item_id,v_product.id,v_item.quantity,v_item.quantity,'fulfilled'); else v_reserve:=least(v_item.quantity,v_available); v_status:=case when v_reserve=v_item.quantity then 'reserved' when v_reserve>0 then 'partial' else 'awaiting_stock' end; insert into public.test_lab_reservations(sale_id,sale_item_id,product_id,quantity_requested,quantity_reserved,status) values(v_sale_id,v_item_id,v_product.id,v_item.quantity,v_reserve,v_status); end if; end loop; update public.test_lab_sales set total_cost=v_total_cost,total_amount=v_total_amount,total_profit=v_total_amount-v_total_cost where id=v_sale_id; insert into public.test_lab_audit_events(operation,entity_type,entity_id,action,details) values(p_operation,'sale',v_sale_id,'created',jsonb_build_object('paid',p_paid,'delivered',p_delivered)); return v_sale_id; end; $$;
create or replace function public.test_lab_mark_sale_paid(p_sale_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_operation text; begin if not public.can_use_test_lab() then raise exception 'Área de teste restrita'; end if; update public.test_lab_sales set payment_status='received',general_status=case when delivery_status='delivered' then 'finalized' else 'active' end,updated_at=now() where id=p_sale_id and general_status<>'cancelled' returning operation into v_operation; if not found then raise exception 'Venda de teste não encontrada'; end if; insert into public.test_lab_audit_events(operation,entity_type,entity_id,action) values(v_operation,'sale',p_sale_id,'paid'); return p_sale_id; end; $$;
create or replace function public.test_lab_mark_sale_delivered(p_sale_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_sale public.test_lab_sales%rowtype; v_item record; v_physical integer; v_other_reserved integer; begin if not public.can_use_test_lab() then raise exception 'Área de teste restrita'; end if; select * into v_sale from public.test_lab_sales where id=p_sale_id for update; if not found or v_sale.general_status='cancelled' then raise exception 'Venda de teste não encontrada'; end if; if v_sale.delivery_status='delivered' then return p_sale_id; end if; for v_item in select * from public.test_lab_sale_items where sale_id=p_sale_id loop select quantity into v_physical from public.test_lab_stock where product_id=v_item.product_id for update; select coalesce(sum(quantity_reserved),0)::integer into v_other_reserved from public.test_lab_reservations where product_id=v_item.product_id and sale_id<>p_sale_id and status in ('reserved','partial'); if v_physical-v_other_reserved<v_item.quantity then raise exception 'Estoque de teste insuficiente para entrega'; end if; end loop; for v_item in select * from public.test_lab_sale_items where sale_id=p_sale_id loop insert into public.test_lab_inventory_movements(operation,product_id,sale_id,movement_type,quantity_delta,notes) values(v_sale.operation,v_item.product_id,p_sale_id,'sale',-v_item.quantity,'Baixa na entrega da venda de teste'); update public.test_lab_reservations set status='fulfilled',quantity_reserved=quantity_requested,updated_at=now() where sale_item_id=v_item.id; end loop; update public.test_lab_sales set delivery_status='delivered',general_status=case when payment_status='received' then 'finalized' else 'active' end,updated_at=now() where id=p_sale_id; insert into public.test_lab_audit_events(operation,entity_type,entity_id,action) values(v_sale.operation,'sale',p_sale_id,'delivered'); return p_sale_id; end; $$;
create or replace function public.test_lab_cancel_sale(p_sale_id uuid,p_reason text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_sale public.test_lab_sales%rowtype; v_item record; begin if not public.can_use_test_lab() then raise exception 'Área de teste restrita'; end if; select * into v_sale from public.test_lab_sales where id=p_sale_id for update; if not found then raise exception 'Venda de teste não encontrada'; end if; if v_sale.general_status='cancelled' then return p_sale_id; end if; if v_sale.delivery_status='delivered' then for v_item in select * from public.test_lab_sale_items where sale_id=p_sale_id loop insert into public.test_lab_inventory_movements(operation,product_id,sale_id,movement_type,quantity_delta,notes) values(v_sale.operation,v_item.product_id,p_sale_id,'cancellation',v_item.quantity,'Estorno do cancelamento de teste'); end loop; else update public.test_lab_reservations set status='cancelled',quantity_reserved=0,updated_at=now() where sale_id=p_sale_id and status in ('reserved','partial','awaiting_stock'); end if; update public.test_lab_sales set general_status='cancelled',updated_at=now(),notes=case when nullif(btrim(p_reason),'') is null then notes when nullif(btrim(notes),'') is null then 'Cancelamento: '||btrim(p_reason) else notes||' | Cancelamento: '||btrim(p_reason) end where id=p_sale_id; insert into public.test_lab_audit_events(operation,entity_type,entity_id,action,details) values(v_sale.operation,'sale',p_sale_id,'cancelled',jsonb_build_object('reason',p_reason)); return p_sale_id; end; $$;
create or replace function public.test_lab_create_purchase_order(p_operation text,p_supplier_id uuid,p_product_id uuid,p_quantity integer,p_unit_cost numeric) returns uuid language plpgsql security definer set search_path=public as $$ declare v_order uuid; begin if not public.can_use_test_lab() then raise exception 'Área de teste restrita'; end if; if p_quantity<=0 then raise exception 'Quantidade inválida'; end if; if not exists(select 1 from public.test_lab_suppliers where id=p_supplier_id and operation=p_operation) then raise exception 'Fornecedor de teste inválido'; end if; if not exists(select 1 from public.test_lab_products where id=p_product_id and operation=p_operation) then raise exception 'Produto de teste inválido'; end if; insert into public.test_lab_purchase_orders(operation,supplier_id) values(p_operation,p_supplier_id) returning id into v_order; insert into public.test_lab_purchase_order_items(purchase_order_id,product_id,quantity_ordered,unit_cost) values(v_order,p_product_id,p_quantity,p_unit_cost); insert into public.test_lab_audit_events(operation,entity_type,entity_id,action) values(p_operation,'purchase_order',v_order,'created'); return v_order; end; $$;
create or replace function public.test_lab_receive_purchase_item(p_item_id uuid,p_quantity integer) returns uuid language plpgsql security definer set search_path=public as $$ declare v_item public.test_lab_purchase_order_items%rowtype; v_order public.test_lab_purchase_orders%rowtype; v_remaining integer; v_status text; v_res record; v_available integer; v_add integer; begin if not public.can_use_test_lab() then raise exception 'Área de teste restrita'; end if; select * into v_item from public.test_lab_purchase_order_items where id=p_item_id for update; if not found then raise exception 'Item de pedido de teste não encontrado'; end if; select * into v_order from public.test_lab_purchase_orders where id=v_item.purchase_order_id for update; v_remaining:=v_item.quantity_ordered-v_item.quantity_received; if p_quantity<=0 or p_quantity>v_remaining then raise exception 'Quantidade inválida. Restante: %',v_remaining; end if; update public.test_lab_purchase_order_items set quantity_received=quantity_received+p_quantity where id=p_item_id; update public.test_lab_products set cost_price=v_item.unit_cost where id=v_item.product_id; insert into public.test_lab_inventory_movements(operation,product_id,purchase_order_item_id,movement_type,quantity_delta,notes) values(v_order.operation,v_item.product_id,p_item_id,'purchase',p_quantity,'Recebimento de pedido de teste'); select greatest(s.quantity-coalesce((select sum(r.quantity_reserved) from public.test_lab_reservations r where r.product_id=v_item.product_id and r.status in ('reserved','partial')),0),0)::integer into v_available from public.test_lab_stock s where s.product_id=v_item.product_id; for v_res in select r.id,r.quantity_requested,r.quantity_reserved from public.test_lab_reservations r join public.test_lab_sales s on s.id=r.sale_id where r.product_id=v_item.product_id and r.status in ('awaiting_stock','partial') and s.general_status<>'cancelled' order by s.created_at,r.id loop exit when v_available<=0; v_add:=least(v_res.quantity_requested-v_res.quantity_reserved,v_available); update public.test_lab_reservations set quantity_reserved=quantity_reserved+v_add,status=case when quantity_reserved+v_add>=quantity_requested then 'reserved' else 'partial' end,updated_at=now() where id=v_res.id; v_available:=v_available-v_add; end loop; select case when bool_and(quantity_received>=quantity_ordered) then 'received' when bool_or(quantity_received>0) then 'partial' else 'pending' end into v_status from public.test_lab_purchase_order_items where purchase_order_id=v_order.id; update public.test_lab_purchase_orders set status=v_status,updated_at=now() where id=v_order.id; insert into public.test_lab_audit_events(operation,entity_type,entity_id,action,details) values(v_order.operation,'purchase_order',v_order.id,'received_item',jsonb_build_object('quantity',p_quantity)); return p_item_id; end; $$;
grant execute on function public.test_lab_reset(text) to authenticated; grant execute on function public.test_lab_create_sale(text,uuid,jsonb,boolean,boolean,text) to authenticated; grant execute on function public.test_lab_mark_sale_paid(uuid) to authenticated; grant execute on function public.test_lab_mark_sale_delivered(uuid) to authenticated; grant execute on function public.test_lab_cancel_sale(uuid,text) to authenticated; grant execute on function public.test_lab_create_purchase_order(text,uuid,uuid,integer,numeric) to authenticated; grant execute on function public.test_lab_receive_purchase_item(uuid,integer) to authenticated;
